// Command thirdparty records the licenses of modules used by release binaries.
package main

import (
	"bytes"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"slices"
	"strings"
)

type module struct {
	Path, Version, Dir string
	Main               bool
	Replace            *module
}

func main() {
	check := flag.Bool("check", false, "fail if THIRD-PARTY.md is stale")
	flag.Parse()
	if err := run(*check); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func run(check bool) error {
	modules := map[string]module{}
	// Match .goreleaser.yaml, including Windows-only dependencies.
	for _, targetOS := range []string{"darwin", "linux", "windows"} {
		for _, arch := range []string{"amd64", "arm64"} {
			cmd := exec.Command("go", "list", "-deps", "-json", "./cmd/duolog")
			cmd.Env = append(os.Environ(), "GOOS="+targetOS, "GOARCH="+arch, "CGO_ENABLED=0")
			var stderr bytes.Buffer
			cmd.Stderr = &stderr
			data, err := cmd.Output()
			if err != nil {
				return fmt.Errorf("go list (%s/%s): %w: %s", targetOS, arch, err, &stderr)
			}
			decoder := json.NewDecoder(bytes.NewReader(data))
			for {
				var pkg struct{ Module *module }
				if err := decoder.Decode(&pkg); err == io.EOF {
					break
				} else if err != nil {
					return err
				}
				if pkg.Module == nil || pkg.Module.Main {
					continue
				}
				m := *pkg.Module
				if m.Replace != nil {
					return fmt.Errorf("%s: replaced modules need review", m.Path)
				}
				modules[m.Path] = m
			}
		}
	}
	names := make([]string, 0, len(modules))
	for name := range modules {
		names = append(names, name)
	}
	slices.Sort(names)
	var output bytes.Buffer
	output.WriteString("# Third-party notices\n\nDuolog release binaries include the modules below. Each module keeps its own\ncopyright and license. The Go standard library is covered by Go's BSD license.\n\nGenerated by `go run ./scripts/thirdparty`. Run `make third-party` to update it.\nThe table covers all operating systems and architectures in `.goreleaser.yaml`.\n\n| Package | Version | License |\n|---|---|---|\n")
	for _, name := range names {
		m := modules[name]
		license, err := moduleLicense(m.Dir)
		if err != nil {
			return fmt.Errorf("%s@%s: %w", name, m.Version, err)
		}
		fmt.Fprintf(&output, "| %s | %s | %s |\n", name, m.Version, license)
	}
	if check {
		current, err := os.ReadFile("THIRD-PARTY.md")
		if err != nil {
			return err
		}
		if !bytes.Equal(current, output.Bytes()) {
			return fmt.Errorf("THIRD-PARTY.md is stale; run make third-party")
		}
		return nil
	}
	return os.WriteFile("THIRD-PARTY.md", output.Bytes(), 0644)
}

func moduleLicense(dir string) (string, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return "", err
	}
	var licenses []string
	for _, entry := range entries {
		name := strings.ToLower(entry.Name())
		if entry.IsDir() || !(name == "license" || strings.HasPrefix(name, "license.") || strings.HasPrefix(name, "license-") || name == "licence" || name == "copying") {
			continue
		}
		data, err := os.ReadFile(filepath.Join(dir, entry.Name()))
		if err != nil {
			return "", err
		}
		license, err := classifyLicense(string(data))
		if err != nil {
			return "", fmt.Errorf("%s: %w", entry.Name(), err)
		}
		if !slices.Contains(licenses, license) {
			licenses = append(licenses, license)
		}
	}
	if len(licenses) == 0 {
		return "", fmt.Errorf("no recognized license file")
	}
	slices.Sort(licenses)
	return strings.Join(licenses, " AND "), nil
}

func classifyLicense(text string) (string, error) {
	text = strings.ToLower(strings.Join(strings.Fields(text), " "))
	for _, forbidden := range []string{"general public license", "mozilla public license", "eclipse public license", "common development and distribution license", "copyleft"} {
		if strings.Contains(text, forbidden) {
			return "", fmt.Errorf("copyleft or unsupported license")
		}
	}
	var licenses []string
	if strings.Contains(text, "permission is hereby granted, free of charge") &&
		strings.Contains(text, "the above copyright notice and this permission notice") &&
		strings.Contains(text, "software is provided") {
		licenses = append(licenses, "MIT")
	}
	if strings.Contains(text, "apache license") &&
		(strings.Contains(text, "version 2.0") || strings.Contains(text, "license, version 2.0")) &&
		strings.Contains(text, "www.apache.org/licenses/") {
		licenses = append(licenses, "Apache-2.0")
	}
	if strings.Contains(text, "redistribution and use in source and binary forms") &&
		strings.Contains(text, "redistributions of source code must retain") &&
		strings.Contains(text, "redistributions in binary form must reproduce") &&
		strings.Contains(text, "this software is provided") {
		if strings.Contains(text, "advertising materials") {
			return "", fmt.Errorf("unsupported BSD advertising clause")
		}
		if strings.Contains(text, "neither the name") && strings.Contains(text, "endorse or promote") {
			licenses = append(licenses, "BSD-3-Clause")
		} else if !strings.Contains(text, "advertising materials") {
			licenses = append(licenses, "BSD-2-Clause")
		}
	}
	if len(licenses) == 0 {
		return "", fmt.Errorf("unknown license; review required")
	}
	// YAML uses MIT for its libyaml-derived files and Apache-2.0 for the rest.
	return strings.Join(licenses, " AND "), nil
}
